/* ============================================================
   claude.ai — RES Night Mode Theme Adaptation
   Install with: Stylus extension → "Write new style" → 
   set to apply on "URLs on the domain: claude.ai"
   ============================================================ */

/* ── Color Palette from original RES theme ──
   Deep bg:      #13001e
   Mid bg:       #1e0b38
   Lift bg:      #291435
   Mint accent:  #14ef9b
   Soft teal:    #7fddc2
   Cyan links:   #41cdff
   Pink header:  #ff6c7d
   Muted mauve:  #896070
   ─────────────────────────────────────────── */


/* ── 1. Root token overrides ── */

:root,
[data-theme="dark"],
[data-theme="light"] {
  --bg-primary:           #13001e;
  --bg-secondary:         #1e0b38;
  --bg-tertiary:          #291435;
  --text-primary:         #14ef9b;
  --text-secondary:       #7fddc2;
  --text-muted:           #896070;
  --accent-link:          #41cdff;
  --accent-header:        #ff6c7d;
  --border-color:         #1e0b38;
  --border-strong:        #291435;
}


/* ── 2. Page base ── */

html,
body {
  background-color: #13001e !important;
  color: #14ef9b !important;
}


/* ── 3. Main layout surfaces ── */

/* Sidebar / nav rail */
[class*="sidebar"],
[class*="Sidebar"],
nav,
[role="navigation"],
[class*="nav-"],
[class*="Nav"] {
  background-color: #13001e !important;
  border-color: #1e0b38 !important;
  color: #14ef9b !important;
}

/* Sidebar conversation items (unselected) */
[class*="conversation"],
[class*="Conversation"],
[class*="chat-item"],
[class*="history-item"] {
  color: #7fddc2 !important;
  border-color: #1e0b38 !important;
}

/* Sidebar active/selected item */
[class*="conversation"][class*="active"],
[class*="conversation"][class*="selected"],
[class*="active"] [class*="conversation"],
[aria-selected="true"] {
  background-color: #1e0b38 !important;
  color: #14ef9b !important;
}

/* Sidebar hover */
[class*="conversation"]:hover,
[class*="chat-item"]:hover {
  background-color: #1e0b38 !important;
}

/* Main content area */
main,
[role="main"],
[class*="main-content"],
[class*="MainContent"],
[class*="chat-window"],
[class*="ChatWindow"] {
  background-color: #13001e !important;
  color: #14ef9b !important;
}


/* ── 4. Top header / toolbar ── */

header,
[class*="header"],
[class*="Header"],
[class*="topbar"],
[class*="TopBar"],
[class*="toolbar"],
[class*="Toolbar"] {
  background-color: #13001e !important;
  border-color: #1e0b38 !important;
  color: #ff6c7d !important;
}

header a,
header button,
[class*="header"] a,
[class*="header"] button {
  color: #41cdff !important;
}


/* ── 5. Claude & human message bubbles ── */

/* Human messages */
[class*="human"],
[class*="Human"],
[data-role="user"],
[class*="user-message"],
[class*="UserMessage"],
[class*="HumanMessage"] {
  background-color: #1e0b38 !important;
  color: #7fddc2 !important;
  border-color: #291435 !important;
}

/* Claude messages */
[class*="assistant"],
[class*="Assistant"],
[data-role="assistant"],
[class*="assistant-message"],
[class*="AssistantMessage"],
[class*="ClaudeMessage"] {
  background-color: #13001e !important;
  color: #14ef9b !important;
}

/* Message container / turn wrapper */
[class*="turn"],
[class*="Turn"],
[class*="message-row"],
[class*="MessageRow"] {
  border-color: #1e0b38 !important;
}

/* General prose text in messages */
[class*="message"] p,
[class*="message"] li,
[class*="message"] span,
[class*="prose"] p,
[class*="prose"] li {
  color: #14ef9b !important;
}

/* Headings in responses */
[class*="message"] h1,
[class*="message"] h2,
[class*="message"] h3,
[class*="message"] h4,
[class*="prose"] h1,
[class*="prose"] h2,
[class*="prose"] h3,
[class*="prose"] h4 {
  color: #7fddc2 !important;
}

/* Links in messages */
[class*="message"] a,
[class*="prose"] a {
  color: #41cdff !important;
  text-decoration-color: #291435 !important;
}

[class*="message"] a:visited,
[class*="prose"] a:visited {
  color: #7fddc2 !important;
}

/* Blockquotes */
[class*="message"] blockquote,
[class*="prose"] blockquote {
  background-color: #1e0b38 !important;
  border-left-color: #14ef9b !important;
  color: #7fddc2 !important;
}

/* Horizontal rules */
[class*="message"] hr,
[class*="prose"] hr {
  border-color: #1e0b38 !important;
}


/* ── 6. Code blocks ── */

pre,
code,
[class*="code-block"],
[class*="CodeBlock"],
[class*="syntax"],
[class*="Syntax"] {
  background-color: #0a0015 !important;
  border-color: #1e0b38 !important;
  color: #7fddc2 !important;
}

/* Inline code */
:not(pre) > code {
  background-color: #1e0b38 !important;
  color: #14ef9b !important;
  border-color: #291435 !important;
}

/* Code block header / filename bar */
[class*="code-header"],
[class*="CodeHeader"],
[class*="code-toolbar"],
[class*="file-name"],
[class*="filename"] {
  background-color: #1e0b38 !important;
  border-color: #291435 !important;
  color: #7fddc2 !important;
}

/* Copy button in code blocks */
[class*="copy"],
[class*="Copy"] {
  color: #41cdff !important;
  background-color: #1e0b38 !important;
  border-color: #291435 !important;
}

[class*="copy"]:hover,
[class*="Copy"]:hover {
  background-color: #291435 !important;
  color: #14ef9b !important;
}


/* ── 7. Input area ── */

[class*="input-area"],
[class*="InputArea"],
[class*="composer"],
[class*="Composer"],
[class*="prompt-input"],
[class*="PromptInput"],
[class*="chat-input"],
[class*="ChatInput"] {
  background-color: #1e0b38 !important;
  border-color: #291435 !important;
  color: #14ef9b !important;
}

/* The textarea itself */
textarea,
[contenteditable="true"],
[role="textbox"] {
  background-color: #1e0b38 !important;
  color: #14ef9b !important;
  caret-color: #14ef9b !important;
  border-color: #291435 !important;
}

textarea::placeholder,
[contenteditable="true"][data-placeholder]::before {
  color: #896070 !important;
}

/* Input wrapper / footer bar */
[class*="input-wrapper"],
[class*="InputWrapper"],
[class*="bottom-bar"],
[class*="BottomBar"],
[class*="footer"],
[class*="Footer"] {
  background-color: #13001e !important;
  border-color: #1e0b38 !important;
}


/* ── 8. Buttons ── */

/* Primary / send button */
button[type="submit"],
[class*="send-button"],
[class*="SendButton"],
[class*="submit-button"],
[class*="SubmitButton"] {
  background-color: #14ef9b !important;
  color: #13001e !important;
  border-color: #14ef9b !important;
}

button[type="submit"]:hover,
[class*="send-button"]:hover,
[class*="SendButton"]:hover {
  background-color: #7fddc2 !important;
  color: #13001e !important;
}

button[type="submit"]:disabled,
[class*="send-button"]:disabled {
  background-color: #291435 !important;
  color: #896070 !important;
  border-color: #291435 !important;
}

/* Secondary / ghost buttons */
button:not([type="submit"]),
[role="button"],
[class*="button"],
[class*="Button"] {
  color: #41cdff !important;
  border-color: #291435 !important;
  background-color: transparent !important;
}

button:not([type="submit"]):hover,
[role="button"]:hover {
  background-color: #1e0b38 !important;
  color: #14ef9b !important;
  border-color: #14ef9b !important;
}


/* ── 9. Dropdowns, menus, modals ── */

[role="menu"],
[role="listbox"],
[class*="dropdown"],
[class*="Dropdown"],
[class*="popover"],
[class*="Popover"],
[class*="modal"],
[class*="Modal"],
[class*="dialog"],
[class*="Dialog"] {
  background-color: #1e0b38 !important;
  border-color: #291435 !important;
  color: #14ef9b !important;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.7) !important;
}

[role="menuitem"],
[role="option"],
[class*="menu-item"],
[class*="MenuItem"],
[class*="dropdown-item"],
[class*="DropdownItem"] {
  color: #7fddc2 !important;
  background-color: transparent !important;
}

[role="menuitem"]:hover,
[role="option"]:hover,
[class*="menu-item"]:hover,
[class*="MenuItem"]:hover {
  background-color: #291435 !important;
  color: #14ef9b !important;
}

/* Modal overlay */
[class*="overlay"],
[class*="Overlay"],
[class*="backdrop"],
[class*="Backdrop"] {
  background-color: rgba(19, 0, 30, 0.85) !important;
}


/* ── 10. Dividers, borders, separators ── */

hr,
[class*="divider"],
[class*="Divider"],
[class*="separator"],
[class*="Separator"] {
  border-color: #1e0b38 !important;
  background-color: #1e0b38 !important;
}


/* ── 11. Tooltips ── */

[role="tooltip"],
[class*="tooltip"],
[class*="Tooltip"] {
  background-color: #291435 !important;
  color: #14ef9b !important;
  border-color: #1e0b38 !important;
}


/* ── 12. Scrollbars (Webkit) ── */

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: #13001e;
}

::-webkit-scrollbar-thumb {
  background-color: #291435;
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background-color: #14ef9b;
}


/* ── 13. Selection highlight ── */

::selection {
  background-color: #14ef9b33;
  color: #14ef9b;
}


/* ── 14. Focus rings ── */

:focus-visible {
  outline-color: #14ef9b !important;
}


/* ── 15. Model selector / settings pills ── */

[class*="model"],
[class*="Model"],
[class*="selector"],
[class*="Selector"],
[class*="pill"],
[class*="Pill"],
[class*="tag"],
[class*="Tag"],
[class*="badge"],
[class*="Badge"] {
  background-color: #1e0b38 !important;
  color: #7fddc2 !important;
  border-color: #291435 !important;
}

[class*="model"]:hover,
[class*="selector"]:hover,
[class*="pill"]:hover {
  background-color: #291435 !important;
  color: #14ef9b !important;
  border-color: #14ef9b !important;
}


/* ── 16. New chat / action buttons in sidebar ── */

[class*="new-chat"],
[class*="NewChat"],
[class*="new-conversation"],
[class*="NewConversation"] {
  background-color: #1e0b38 !important;
  color: #14ef9b !important;
  border-color: #291435 !important;
}

[class*="new-chat"]:hover,
[class*="NewChat"]:hover {
  background-color: #291435 !important;
  border-color: #14ef9b !important;
}


/* ── 17. Loading / thinking states ── */

[class*="thinking"],
[class*="Thinking"],
[class*="loading"],
[class*="Loading"],
[class*="spinner"],
[class*="Spinner"] {
  color: #7fddc2 !important;
  border-color: #14ef9b !important;
}

[class*="skeleton"],
[class*="Skeleton"],
[class*="shimmer"],
[class*="Shimmer"] {
  background: linear-gradient(
    90deg,
    #1e0b38 25%,
    #291435 50%,
    #1e0b38 75%
  ) !important;
  background-size: 200% 100% !important;
}


/* ── 18. Artifacts / canvas panel ── */

[class*="artifact"],
[class*="Artifact"],
[class*="canvas"],
[class*="Canvas"],
[class*="preview"],
[class*="Preview"] {
  background-color: #1e0b38 !important;
  border-color: #291435 !important;
  color: #14ef9b !important;
}

[class*="artifact-header"],
[class*="ArtifactHeader"],
[class*="preview-toolbar"] {
  background-color: #13001e !important;
  border-color: #1e0b38 !important;
  color: #7fddc2 !important;
}


/* ── 19. Typography catch-all ── */

h1, h2, h3, h4, h5, h6 {
  color: #7fddc2 !important;
}

p, li, span, label, td, th {
  color: #14ef9b !important;
}

a {
  color: #41cdff !important;
}

a:visited {
  color: #7fddc2 !important;
}

strong, b {
  color: #14ef9b !important;
}

em, i {
  color: #7fddc2 !important;
}

/* Muted / helper text */
[class*="muted"],
[class*="Muted"],
[class*="hint"],
[class*="Hint"],
[class*="caption"],
[class*="Caption"],
[class*="secondary"],
small {
  color: #896070 !important;
}
